<script setup lang="ts">
import { onMounted, reactive, ref, watch } from 'vue';
type Request=(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<any>;
const props=defineProps<{section:string;request:Request;readonly:boolean;manage:boolean}>();
const busy=ref(false),error=ref(''),notice=ref(''),data=ref<any>({}),accounts=ref<any[]>([]),customers=ref<any[]>([]);
const profile=reactive({brandName:'',supportEmail:'',portalEnabled:false,expectedVersion:0});
const field=reactive({entityType:'CUSTOMER',fieldKey:'',label:'',dataType:'TEXT',required:false,sectionName:'扩展信息',position:100,options:'',readRoles:['TENANT_ADMIN','SALES_MANAGER','SALES','VIEWER'],writeRoles:['TENANT_ADMIN','SALES_MANAGER','SALES'],status:'ACTIVE'});
const tag=reactive({name:'',color:'#4F8F6B',status:'ACTIVE'});const dictionary=reactive({itemCode:'',label:'',position:100,active:true});
const account=reactive({customerId:'',email:'',displayName:'',initialPassword:''});
const extensionCustomer=ref(''),extensions=ref<any>({fields:[],values:[],tags:[]}),extensionValues=reactive<Record<string,any>>({});
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'操作未完成';}finally{busy.value=false;}}
function sync(){const p=data.value.profile??{};Object.assign(profile,{brandName:p.brandName??'',supportEmail:p.supportEmail??'',portalEnabled:!!p.portalEnabled,expectedVersion:p.version??0});}
async function load(){if(props.section==='portal-accounts'){const [a,c]=await Promise.all([props.request('/portal-accounts'),props.request('/customers/options?pageSize=100&writable=false')]);accounts.value=a;customers.value=c.items??[];account.customerId=customers.value[0]?.id??'';}else{const [configuration,c]=await Promise.all([props.request('/configuration'),props.request('/customers/options?pageSize=100&writable=false').catch(()=>({items:[]}))]);data.value=configuration;customers.value=c.items??[];sync();}}
async function saveProfile(){await run(async()=>{data.value.profile=await props.request('/configuration/profile','PATCH',profile);sync();notice.value='门户外观与开关已保存';});}
async function applyTemplate(code:string){if(!confirm('应用行业模板会新增模板字段并更新工单类型，已有数据不会删除。继续吗？'))return;await run(async()=>{const r=await props.request(`/configuration/templates/${code}/apply`,'POST');notice.value=`模板已应用：新增 ${r.fieldsCreated} 个字段，处理 ${r.ticketTypesApplied} 个工单类型`;await load();});}
async function createField(){await run(async()=>{await props.request('/configuration/fields','POST',{...field,options:field.options.split(/[，,\n]/).map(x=>x.trim()).filter(Boolean),expectedVersion:0},{'Idempotency-Key':crypto.randomUUID()});Object.assign(field,{fieldKey:'',label:'',options:''});notice.value='自定义字段已新增';await load();});}
async function saveField(row:any){await run(async()=>{await props.request('/configuration/fields/'+row.id,'PATCH',{entityType:row.entityType,fieldKey:row.fieldKey,label:row.label,dataType:row.dataType,required:row.required,sectionName:row.sectionName,position:Number(row.position),options:row.options??[],readRoles:row.readRoles,writeRoles:row.writeRoles,status:row.status,expectedVersion:row.version});notice.value='字段已保存';await load();});}
async function createTag(){await run(async()=>{await props.request('/configuration/tags','POST',{...tag,expectedVersion:0},{'Idempotency-Key':crypto.randomUUID()});tag.name='';notice.value='客户标签已新增';await load();});}
async function saveTag(row:any){await run(async()=>{await props.request('/configuration/tags/'+row.id,'PATCH',{name:row.name,color:row.color,status:row.status,expectedVersion:row.version});notice.value='标签已保存';await load();});}
async function saveStage(row:any){await run(async()=>{await props.request('/configuration/stages/'+row.id,'PATCH',{label:row.label,position:Number(row.position),probability:Number(row.probability),active:row.active,expectedVersion:row.version});notice.value='阶段显示已保存';await load();});}
async function saveNumber(row:any){await run(async()=>{await props.request('/configuration/numbers/'+row.id,'PATCH',{prefix:row.prefix,includeYear:row.includeYear,padding:Number(row.padding),expectedVersion:row.version});notice.value='编号规则已保存；只影响后续新单据';await load();});}
async function saveApproval(row:any){await run(async()=>{await props.request('/configuration/approval/'+row.id,'PATCH',{name:row.name,minimumAmountCents:Number(row.minimumAmountCents),active:row.active,expectedVersion:row.version});notice.value='报价审批规则已保存';await load();});}
async function createDictionary(){await run(async()=>{await props.request('/configuration/dictionaries/TICKET_TYPE','POST',{...dictionary,expectedVersion:0},{'Idempotency-Key':crypto.randomUUID()});Object.assign(dictionary,{itemCode:'',label:''});notice.value='工单类型已新增';await load();});}
async function saveDictionary(row:any){await run(async()=>{await props.request('/configuration/dictionaries/'+row.dictionaryType+'/'+row.id,'PATCH',{itemCode:row.itemCode,label:row.label,position:Number(row.position),active:row.active,expectedVersion:row.version});notice.value='字典项已保存';await load();});}
async function createAccount(){await run(async()=>{await props.request('/portal-accounts','POST',account,{'Idempotency-Key':crypto.randomUUID()});Object.assign(account,{email:'',displayName:'',initialPassword:''});notice.value='客户门户账号已开通；请安全地把初始密码交给客户联系人';await load();});}
async function saveAccount(row:any,reset=false){let next='';if(reset){next=prompt('输入新的临时密码（至少 12 位）')??'';if(!next)return;}await run(async()=>{await props.request('/portal-accounts/'+row.id,'PATCH',{displayName:row.displayName,status:row.status,mustChangePassword:reset?true:row.mustChangePassword,newPassword:next||null,expectedVersion:row.version});notice.value=reset?'密码已重置，旧门户会话已撤销':'门户账号已保存';await load();});}
async function loadExtensions(){if(!extensionCustomer.value){extensions.value={fields:[],values:[],tags:[]};return;}await run(async()=>{extensions.value=await props.request('/customers/'+extensionCustomer.value+'/extensions');for(const key of Object.keys(extensionValues))delete extensionValues[key];for(const row of extensions.value.values??[])extensionValues[row.fieldId]=row.value;});}
async function saveExtensions(){await run(async()=>{const tags=(extensions.value.tags??[]).filter((x:any)=>x.assigned).map((x:any)=>x.id);extensions.value=await props.request('/customers/'+extensionCustomer.value+'/extensions','PUT',{values:{...extensionValues},tagIds:tags});notice.value='客户扩展字段与标签已保存';});}
watch(()=>props.section,()=>run(load));onMounted(()=>run(load));
</script>

<template>
 <section class="p4">
  <div class="page-heading"><div><span class="eyebrow">P4 · TENANT PRODUCTIZATION</span><h1>{{section==='portal-accounts'?'客户门户账号':'行业配置中心'}}</h1><p>{{section==='portal-accounts'?'由企业管理员把指定客户联系人开通为外部账号；每个账号只能访问绑定客户。':'把行业差异沉淀为企业配置，不改动稳定业务状态码。'}}</p></div><a class="btn secondary" href="?portal=1" target="_blank">打开客户门户</a></div>
  <div v-if="error" class="p4-alert bad">{{error}}</div><div v-if="notice" class="p4-alert ok">{{notice}}</div>
  <template v-if="section==='portal-accounts'">
   <form v-if="manage&&!readonly" class="card p4-form" @submit.prevent="createAccount"><h2>开通门户账号</h2><div class="p4-grid"><label>绑定客户<select v-model="account.customerId" required><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>联系人姓名<input v-model="account.displayName" required maxlength="100"/></label><label>登录邮箱<input v-model="account.email" type="email" required maxlength="254"/></label><label>初始密码<input v-model="account.initialPassword" type="password" minlength="12" maxlength="72" required autocomplete="new-password"/></label></div><p>首次登录必须改密；内部员工账号与客户门户账号互不通用。</p><button class="btn primary" :disabled="busy">开通账号</button></form>
   <section class="card p4-table"><div class="p4-title"><h2>现有账号</h2><span>{{accounts.length}} 个</span></div><div class="table-scroll"><table><thead><tr><th>客户</th><th>姓名</th><th>邮箱</th><th>状态</th><th>最近登录</th><th>操作</th></tr></thead><tbody><tr v-for="row in accounts" :key="row.id"><td>{{row.customerName}}</td><td><input v-model="row.displayName" :disabled="!manage||readonly"/></td><td>{{row.email}}</td><td><select v-model="row.status" :disabled="!manage||readonly"><option>ACTIVE</option><option>DISABLED</option></select></td><td>{{row.lastLoginAt?new Date(row.lastLoginAt).toLocaleString():'尚未登录'}}</td><td><button v-if="manage&&!readonly" class="text-button" @click="saveAccount(row)">保存</button><button v-if="manage&&!readonly" class="text-button" @click="saveAccount(row,true)">重置密码</button></td></tr><tr v-if="!accounts.length"><td colspan="6" class="empty-cell">暂无客户门户账号</td></tr></tbody></table></div></section>
  </template>
  <template v-else>
   <section class="p4-split"><form class="card p4-form" @submit.prevent="saveProfile"><h2>企业品牌与门户</h2><label>门户显示名称<input v-model="profile.brandName" required maxlength="100" :disabled="!manage||readonly"/></label><label>支持邮箱<input v-model="profile.supportEmail" type="email" maxlength="254" :disabled="!manage||readonly"/></label><label class="p4-check"><input v-model="profile.portalEnabled" type="checkbox" :disabled="!manage||readonly"/>启用客户门户登录</label><button v-if="manage&&!readonly" class="btn primary" :disabled="busy">保存配置</button></form><section class="card p4-form"><h2>行业模板</h2><p>模板只新增缺失字段、刷新同编码工单类型，不覆盖企业已有字段值。</p><button v-for="t in data.templates" :key="t.code" class="p4-template" :disabled="!manage||readonly||busy" @click="applyTemplate(t.code)"><strong>{{t.name}}</strong><span>{{t.description}}</span></button></section></section>
   <section class="card p4-form"><div class="p4-title"><div><h2>自定义字段与表单布局</h2><p>字段编码和类型创建后锁定，避免历史数据失去含义。</p></div></div><form v-if="manage&&!readonly" class="p4-inline" @submit.prevent="createField"><select v-model="field.entityType"><option>CUSTOMER</option><option>CONTACT</option><option>LEAD</option><option>OPPORTUNITY</option><option>TICKET</option></select><input v-model="field.fieldKey" required pattern="[a-z][a-z0-9_]{1,39}" placeholder="字段编码"/><input v-model="field.label" required placeholder="显示名称"/><select v-model="field.dataType"><option>TEXT</option><option>TEXTAREA</option><option>NUMBER</option><option>DATE</option><option>BOOLEAN</option><option>SELECT</option><option>MULTI_SELECT</option></select><input v-model="field.sectionName" required placeholder="分组"/><input v-if="['SELECT','MULTI_SELECT'].includes(field.dataType)" v-model="field.options" placeholder="选项，用逗号分隔"/><button class="btn secondary">新增字段</button></form><div class="table-scroll"><table><thead><tr><th>对象 / 编码</th><th>名称</th><th>分组</th><th>类型</th><th>排序</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.fields" :key="row.id"><td>{{row.entityType}}<small>{{row.fieldKey}}</small></td><td><input v-model="row.label" :disabled="!manage||readonly"/></td><td><input v-model="row.sectionName" :disabled="!manage||readonly"/></td><td>{{row.dataType}}</td><td><input v-model.number="row.position" type="number" min="0" max="10000" :disabled="!manage||readonly"/></td><td><select v-model="row.status" :disabled="!manage||readonly"><option>ACTIVE</option><option>ARCHIVED</option></select></td><td><button v-if="manage&&!readonly" class="text-button" @click="saveField(row)">保存</button></td></tr></tbody></table></div></section>
   <section class="p4-split"><section class="card p4-form"><h2>客户标签</h2><form v-if="manage&&!readonly" class="p4-inline" @submit.prevent="createTag"><input v-model="tag.name" required placeholder="标签名称"/><input v-model="tag.color" type="color"/><button class="btn secondary">新增</button></form><div v-for="row in data.tags" :key="row.id" class="p4-row"><input v-model="row.name" :disabled="!manage||readonly"/><input v-model="row.color" type="color" :disabled="!manage||readonly"/><select v-model="row.status" :disabled="!manage||readonly"><option>ACTIVE</option><option>ARCHIVED</option></select><button v-if="manage&&!readonly" class="text-button" @click="saveTag(row)">保存</button></div></section><section class="card p4-form"><h2>工单类型</h2><form v-if="manage&&!readonly" class="p4-inline" @submit.prevent="createDictionary"><input v-model="dictionary.itemCode" required pattern="[A-Z0-9_]{1,40}" placeholder="编码"/><input v-model="dictionary.label" required placeholder="名称"/><button class="btn secondary">新增</button></form><div v-for="row in (data.dictionaries??[]).filter((x:any)=>x.dictionaryType==='TICKET_TYPE')" :key="row.id" class="p4-row"><code>{{row.itemCode}}</code><input v-model="row.label" :disabled="!manage||readonly"/><label class="p4-check"><input v-model="row.active" type="checkbox" :disabled="!manage||readonly"/>启用</label><button v-if="manage&&!readonly" class="text-button" @click="saveDictionary(row)">保存</button></div></section></section>
   <section class="card p4-form"><h2>销售与工单阶段显示</h2><div class="table-scroll"><table><thead><tr><th>流程</th><th>状态码</th><th>显示名称</th><th>排序</th><th>概率</th><th>启用</th><th>操作</th></tr></thead><tbody><tr v-for="row in data.stages" :key="row.id"><td>{{row.processType}}</td><td><code>{{row.stageCode}}</code></td><td><input v-model="row.label" :disabled="!manage||readonly"/></td><td><input v-model.number="row.position" type="number" :disabled="!manage||readonly"/></td><td><input v-model.number="row.probability" type="number" min="0" max="100" :disabled="!manage||readonly"/></td><td><input v-model="row.active" type="checkbox" :disabled="!manage||readonly||row.terminal"/></td><td><button v-if="manage&&!readonly" class="text-button" @click="saveStage(row)">保存</button></td></tr></tbody></table></div></section>
   <section class="p4-split"><section class="card p4-form"><h2>编号规则</h2><div v-for="row in data.numberRules" :key="row.id" class="p4-number"><strong>{{row.documentType}}</strong><input v-model="row.prefix" pattern="[A-Z0-9]{1,10}" maxlength="10" :disabled="!manage||readonly"/><label class="p4-check"><input v-model="row.includeYear" type="checkbox" :disabled="!manage||readonly"/>年份</label><input v-model.number="row.padding" type="number" min="3" max="9" :disabled="!manage||readonly"/><button v-if="manage&&!readonly" class="text-button" @click="saveNumber(row)">保存</button></div></section><section v-if="data.approvalRule" class="card p4-form"><h2>报价审批规则</h2><label>规则名称<input v-model="data.approvalRule.name" :disabled="!manage||readonly"/></label><label>规则记录金额门槛（分）<input v-model.number="data.approvalRule.minimumAmountCents" type="number" min="0" :disabled="!manage||readonly"/></label><label class="p4-check"><input v-model="data.approvalRule.active" type="checkbox" :disabled="!manage||readonly"/>启用并写入审批快照</label><button v-if="manage&&!readonly" class="btn secondary" @click="saveApproval(data.approvalRule)">保存审批规则</button></section></section>
   <section class="card p4-form"><div class="p4-title"><div><h2>客户扩展资料体验</h2><p>选择客户后，按当前角色的字段读写权限填写自定义资料并分配标签。</p></div><select v-model="extensionCustomer" @change="loadExtensions"><option value="">选择客户</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></div><form v-if="extensionCustomer" @submit.prevent="saveExtensions"><div class="p4-grid"><label v-for="f in extensions.fields" :key="f.id">{{f.label}}<select v-if="f.dataType==='SELECT'" v-model="extensionValues[f.id]" :required="f.required"><option value="">请选择</option><option v-for="o in f.options" :key="o" :value="o">{{o}}</option></select><textarea v-else-if="f.dataType==='TEXTAREA'" v-model="extensionValues[f.id]" rows="3" :required="f.required"></textarea><input v-else-if="f.dataType==='BOOLEAN'" v-model="extensionValues[f.id]" type="checkbox"/><input v-else v-model="extensionValues[f.id]" :type="f.dataType==='NUMBER'?'number':f.dataType==='DATE'?'date':'text'" :required="f.required"/></label></div><div class="p4-tags"><label v-for="t in extensions.tags" :key="t.id" class="p4-check"><input v-model="t.assigned" type="checkbox"/><i :style="{background:t.color}"></i>{{t.name}}</label></div><button class="btn primary" :disabled="busy">保存扩展资料</button></form><p v-else>从上方选择一个可见客户开始填写。</p></section>
  </template>
 </section>
</template>

<style scoped>
.p4-alert{padding:12px 15px;border-radius:7px;margin:12px 0;font-size:13px}.p4-alert.bad{background:#fff0f1;color:#9d2433}.p4-alert.ok{background:#eaf5ed;color:#286045}.p4-split{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:20px 0}.p4-form{padding:24px;margin:20px 0}.p4-split .p4-form{margin:0}.p4-form h2{font-size:19px;margin:0 0 16px}.p4-form p{font-size:13px;line-height:1.7;color:#647269}.p4-form>label{display:flex;flex-direction:column;gap:8px;font-size:13px;margin:14px 0}.p4 input,.p4 select,.p4 textarea{padding:9px;border:1px solid #ccd8d0;border-radius:5px;background:#fff;min-width:0}.p4-check{display:flex!important;flex-direction:row!important;align-items:center;gap:8px!important}.p4-template{display:flex;flex-direction:column;gap:6px;width:100%;padding:13px;margin:8px 0;border:1px solid #d6e2da;border-radius:7px;background:#fff;text-align:left;color:#294c38}.p4-template span{font-size:12px;color:#6b786f}.p4-inline{display:flex;gap:9px;align-items:center;flex-wrap:wrap;padding:14px;background:#f5f8f6;border-radius:8px;margin-bottom:15px}.p4-row,.p4-number{display:grid;grid-template-columns:1fr 70px 120px 60px;gap:8px;align-items:center;padding:10px 0;border-bottom:1px solid #e6ece8}.p4-number{grid-template-columns:100px 100px 90px 65px 60px}.p4-title{display:flex;justify-content:space-between;align-items:center}.p4-title p{margin:4px 0}.p4-table{overflow:hidden;margin-top:20px}.p4-table .p4-title{padding:20px}.p4-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 18px}.p4 table input,.p4 table select{max-width:180px}.p4 table small{display:block;color:#718078;margin-top:4px}@media(max-width:800px){.p4-split,.p4-grid{grid-template-columns:1fr}.p4-row,.p4-number{grid-template-columns:1fr 1fr}.p4-inline>*{flex:1 1 160px}}
.p4-tags{display:flex;gap:14px;flex-wrap:wrap;padding:16px 0}.p4-tags i{width:10px;height:10px;border-radius:50%}.p4-title{gap:18px}@media(max-width:800px){.p4-title{align-items:flex-start;flex-direction:column}}
</style>
